import{onReady}from"./dom-ready.js";import{getCurrentPageConfig}from"./page-manifest.js";import{loadLegacyBundleForPage}from"./legacy-bridge.js";onReady(async()=>{const e=getCurrentPageConfig(window.location.pathname);document.documentElement.dataset.moduleBootstrap="ready",document.documentElement.dataset.pageModule=e.name;try{await loadLegacyBundleForPage(e),window.dispatchEvent(new CustomEvent("india:modules-ready",{detail:{page:e.name,scripts:e.legacyScripts,dataModules:e.dataModules}}))}catch(a){console.error("[Incredible India] Modular bootstrap failed:",a),window.dispatchEvent(new CustomEvent("india:modules-error",{detail:{page:e.name,error:a}}))}});